#!/usr/bin/env node
/* ===========================================================================
 * build-hadith-data.mjs — turn the saved sunnah.com pages in data/ into the
 * compact JSON the app reads from HadithData/.
 *
 *   input : data/<collection>/<collection>_<book>.txt   (a saved sunnah.com page)
 *   output: HadithData/catalog.json                     (collections and books)
 *           HadithData/<collection>/<book>.json         (one file per kitab)
 *
 * The pages are machine-generated by sunnah.com, so instead of pulling in an
 * HTML parser (this project has no dependencies) each page is sliced on its own
 * markers: `actualHadithContainer` for a hadith, `div.chapter` for a chapter
 * banner, `book_info` for the kitab names, `pageType` counts for verification.
 * Every run checks what it extracted against independent counts taken from the
 * same page (containers, narrator blocks, grade blocks, the "N hadith" comment,
 * `var collection` / `var bookID`), so a structural change fails loudly instead
 * of silently losing text.
 *
 * Hadith fields
 *   n, suffix   sunnah.com number and its letter ("690" + "b")
 *   ref         the sticky label, e.g. "Sahih al-Bukhari 1"
 *   slug        canonical link, e.g. "bukhari:1" → https://sunnah.com/bukhari:1
 *   inBook      position inside the kitab (the <a name=N> anchor)
 *   inBookRef   the page's own "Book 1, Hadith 1" line
 *   ch          index into the file's `chapters` (−1 = before any chapter)
 *   narrator    the "Narrated …" block when the page has one, else null
 *   en          English translation (paragraph breaks kept as newlines)
 *   ar.sanad    the chain of narration  (may be an empty string)
 *   ar.matn     the hadith text itself  (may be an empty string)
 *   grade, gradeAr, grader   only Sunan Abi Dawud carries a grade line
 *
 * Chapter fields: n (English counter), nAr (Arabic counter — they can differ),
 * en, ar, intro (Arabic preamble, Bukhari only, may be an empty string).
 *
 * Usage:
 *   node tools/build-hadith-data.mjs            build only
 *   node tools/build-hadith-data.mjs --clean    build, then remove data/
 * =========================================================================== */

import { readFile, writeFile, mkdir, readdir, rm } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = path.join(ROOT, 'data');
const OUTPUT = path.join(ROOT, 'HadithData');

/* Display names for the collections (the pages themselves only carry a slug). */
const COLLECTIONS = {
    bukhari: { english: 'Sahih al-Bukhari', arabic: 'صحيح البخاري' },
    muslim: { english: 'Sahih Muslim', arabic: 'صحيح مسلم' },
    abudawud: { english: 'Sunan Abi Dawud', arabic: 'سنن أبي داود' }
};

/* Reviewers that appear only in Arabic in the grade table. */
const REVIEWERS = { 'الألباني': 'Al-Albani' };

const CONTAINER_RE =
    /<div class="actualHadithContainer hadith_container_([a-z]+)" id=h([0-9a-zA-Z]+)>/g;
const ARABIC_SPAN_RE =
    /<span class="?(arabic_sanad|arabic_text_details)[^>]*>([\s\S]*?)<\/span>/g;
const CONTAINER_END = '<!-- end actual hadith container -->';
const HADITH_END = '<!-- End hadith -->';

/* --------------------------------------------------------------- text ---- */

function decodeEntities(value) {
    return value
        .replace(/&nbsp;/gi, ' ')
        .replace(/&quot;/gi, '"')
        .replace(/&#39;|&apos;/gi, "'")
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&#(\d+);/g, (match, code) => String.fromCodePoint(Number(code)))
        .replace(/&#x([0-9a-f]+);/gi, (match, code) => String.fromCodePoint(parseInt(code, 16)))
        .replace(/&amp;/gi, '&');       // last, so "&amp;lt;" stays literal
}

/* Visible text of a fragment: paragraph tags become line breaks, other tags
   drop, entities decode, runs of spaces collapse. English keeps its breaks. */
function text(fragment) {
    if (!fragment) return '';
    return decodeEntities(fragment
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/(p|div|tr|td)>/gi, '\n')
        .replace(/<[^>]*>/g, ''))
        .replace(/[^\S\n]+/g, ' ')
        .replace(/ ?\n ?/g, '\n')
        .replace(/\n{2,}/g, '\n')
        .trim();
}

/* Same, collapsed to one line: for Arabic and for one-line fields. */
function line(fragment) {
    return text(fragment).replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
}

/* The part of `html` between a start marker and the first of several end
   markers — the shape sunnah.com pages are cut into sections with. */
function sliceBetween(html, startMarker, endMarkers) {
    const start = html.indexOf(startMarker);
    if (start < 0) return '';
    const from = start + startMarker.length;
    let end = -1;
    for (const marker of endMarkers) {
        const found = html.indexOf(marker, from);
        if (found >= 0 && (end < 0 || found < end)) end = found;
    }
    return html.slice(from, end < 0 ? html.length : end);
}

function numberFrom(pattern, value) {
    const match = pattern.exec(value);
    return match ? Number(match[1]) : null;
}

function findText(pattern, value) {
    return text(pattern.exec(value)?.[1] || '');
}

/* ------------------------------------------------------------- pieces ---- */

/* Arabic is a sequence of sanad (chain) and text_details (matn) spans that can
   interleave and repeat, so all of them are concatenated in document order. */
function parseArabic(containerHtml) {
    const block = sliceBetween(containerHtml, '<div class="arabic_hadith_full',
        [HADITH_END, '<div class=bottomItems>', '<table class=hadith_reference']);
    const sanad = [];
    const matn = [];
    for (const match of block.matchAll(ARABIC_SPAN_RE)) {
        const value = line(match[2]);
        if (!value) continue;                       // empty spans are common
        (match[1] === 'arabic_sanad' ? sanad : matn).push(value);
    }
    if (!sanad.length && !matn.length) {
        const fallback = line(block);               // never lose the text
        if (fallback) matn.push(fallback);
    }
    return { sanad: sanad.join(' '), matn: matn.join(' ') };
}

function parseEnglish(containerHtml) {
    const block = sliceBetween(containerHtml, '<div class="english_hadith_full">',
        ['<div class="arabic_hadith_full', HADITH_END, '<div class=bottomItems>']);
    const narratorMarker = '<div class=hadith_narrated>';
    const detailsMarker = '<div class=text_details>';
    const narratorAt = block.indexOf(narratorMarker);
    const detailsAt = block.indexOf(detailsMarker);
    if (detailsAt < 0) {
        return { narrator: null, english: text(block) };
    }
    const narrator = narratorAt >= 0
        ? text(block.slice(narratorAt + narratorMarker.length, detailsAt))
        : '';
    return {
        narrator: narrator || null,
        english: text(block.slice(detailsAt + detailsMarker.length))
    };
}

function parseReference(containerHtml) {
    const link = /<b>Reference<\/b><\/td><td>[^<]*<a href="\/([^"]+)">([\s\S]*?)<\/a>/
        .exec(containerHtml);
    const parts = /^([a-z]+):(\d+)([a-z]?)$/.exec(link ? link[1] : '');
    return {
        slug: link ? link[1] : null,
        ref: link ? line(link[2]) : null,
        number: parts ? Number(parts[2]) : null,
        suffix: parts ? parts[3] : '',
        inBookRef: findText(/In-book reference<\/td><td>([\s\S]*?)<\/td>/, containerHtml)
            .replace(/^:\s*/, '')
    };
}

/* Sunan Abi Dawud carries a grade table; its English cells can be empty and
   the table itself can be missing, so all three shapes are handled. */
function parseGrade(containerHtml) {
    const start = containerHtml.indexOf('<div class=hadith_annotation>');
    if (start < 0) return null;
    const referenceAt = containerHtml.indexOf('<table class=hadith_reference', start);
    const block = containerHtml.slice(start,
        referenceAt < 0 ? containerHtml.length : referenceAt);
    const cells = [];
    for (const match of block.matchAll(/<td([^>]*)>([\s\S]*?)<\/td>/g)) {
        const value = line(match[2]);
        if (value) cells.push({ attrs: match[1], value });
    }
    const englishCell = cells.find(cell =>
        /english_grade/.test(cell.attrs) && !/^grade\s*:/i.test(cell.value));
    const arabicCell = cells.find(cell =>
        /arabic_grade/.test(cell.attrs) && !/^حكم\s*:/.test(cell.value));
    const english = englishCell ? splitReviewer(englishCell.value) : null;
    const arabic = arabicCell ? splitReviewer(arabicCell.value) : null;
    if (!english && !arabic) return null;
    return {
        grade: english ? english.value : null,
        gradeAr: arabic ? arabic.value : null,
        grader: (english && english.reviewer) || (arabic && arabic.reviewer) || null
    };
}

function splitReviewer(value) {
    const match = /^(.*?)\s*\(([^()]+)\)\s*$/.exec(value);
    if (!match) return { value, reviewer: null };
    return { value: match[1].trim(), reviewer: REVIEWERS[match[2]] || match[2] };
}

/* ------------------------------------------------------------ outline ---- */

/* Chapters and their Arabic preambles, each kept with its position in the page
   so a hadith can be attached to the chapter above it. */
function parseOutline(content) {
    const chapters = [];
    for (const match of content.matchAll(/<div class=chapter>/g)) {
        const end = content.indexOf('<div class=clear></div>', match.index);
        const chunk = content.slice(match.index, end < 0 ? match.index + 2000 : end);
        chapters.push({
            index: match.index,
            n: numberFrom(/class=echapno>\((\d+)\)</, chunk),
            nAr: numberFrom(/class=achapno>\((\d+)\)</, chunk),
            en: findText(/class=englishchapter>([\s\S]*?)<\/div>/, chunk)
                .replace(/^Chapter:\s*/, ''),
            ar: line(/class="arabicchapter arabic">([\s\S]*?)<\/div>/.exec(chunk)?.[1] || ''),
            intro: ''
        });
    }
    for (const match of content.matchAll(/<div class="arabic achapintro aconly">([\s\S]*?)<\/div>/g)) {
        const intro = line(match[1]);
        if (!intro) continue;
        let owner = null;
        for (const chapter of chapters) if (chapter.index < match.index) owner = chapter;
        if (owner) owner.intro = owner.intro ? owner.intro + ' ' + intro : intro;
    }
    return chapters;
}

function parseBookInfo(content) {
    return {
        english: findText(/class="book_page_english_name">([\s\S]*?)<\/div>/, content),
        arabic: line(/class="book_page_arabic_name arabic">([\s\S]*?)<\/div>/.exec(content)?.[1] || '')
    };
}

/* --------------------------------------------------------------- page ---- */

function bookNumberOf(fileName) {
    return Number(/_(\d+)\.txt$/.exec(fileName)?.[1] || 0);
}

function parsePage(content, { collection, bookNumber, fileName, report }) {
    const containerMatches = [...content.matchAll(CONTAINER_RE)];
    const chapters = parseOutline(content);

    /* Where each chapter starts, so a hadith can be attached to the one above. */
    const chapterAt = chapters.map(chapter => chapter.index);

    const hadiths = containerMatches.map((match, index) => {
        const next = containerMatches[index + 1];
        const closeAt = content.indexOf(CONTAINER_END, match.index);
        const limit = Math.min(
            closeAt < 0 ? content.length : closeAt,
            next ? next.index : content.length);
        const containerHtml = content.slice(match.index, limit);

        const arabic = parseArabic(containerHtml);
        const english = parseEnglish(containerHtml);
        const reference = parseReference(containerHtml);
        const grade = parseGrade(containerHtml);
        const inBookAnchor = /<a name=(\d+)><\/a>/.exec(containerHtml);
        let chapterIndex = -1;
        for (let i = 0; i < chapterAt.length; i += 1) {
            if (chapterAt[i] < match.index) chapterIndex = i;
        }

        const hadith = {
            n: reference.number,
            suffix: reference.suffix,
            ref: reference.ref,
            slug: reference.slug,
            inBook: inBookAnchor ? Number(inBookAnchor[1]) : null,
            inBookRef: reference.inBookRef,
            ch: chapterIndex,
            narrator: english.narrator,
            en: english.english,
            ar: arabic,
            grade: grade ? grade.grade : null,
            gradeAr: grade ? grade.gradeAr : null,
            grader: grade ? grade.grader : null
        };

        /* Nothing may come out empty — a silent loss here would be a lost hadith. */
        const label = reference.ref || `#${index + 1}`;
        const hasArabic = Boolean(hadith.ar.sanad || hadith.ar.matn);
        /* A few sunnah.com pages ship one side empty — Muslim 2525a, for one,
           has no English at all. Keep the hadith and report the hole. */
        if (!hadith.en && !hasArabic) {
            report.errors.push(`${fileName}: ${label} has no text at all`);
        } else if (!hadith.en) {
            report.gaps.push(`${fileName}: ${label} has no English text (kept, Arabic only)`);
        } else if (!hasArabic) {
            report.gaps.push(`${fileName}: ${label} has no Arabic text (kept, English only)`);
        }
        if (!hadith.slug) report.errors.push(`${fileName}: ${label} has no reference link`);
        return hadith;
    });

    /* Independent counts straight from the page markup. */
    const markers = {
        containers: containerMatches.length,
        narrated: (content.match(/<div class=hadith_narrated>/g) || []).length,
        grades: (content.match(/<div class=hadith_annotation>/g) || []).length,
        comment: numberFrom(/<b>(\d+)<\/b> hadith/, content),
        collection: /var collection = '([a-z]+)'/.exec(content)?.[1],
        bookID: Number(/var bookID = '(\d+)'/.exec(content)?.[1])
    };
    const parsed = {
        narrated: hadiths.filter(hadith => hadith.narrator).length,
        grades: hadiths.filter(hadith => hadith.grade || hadith.gradeAr).length
    };
    if (markers.narrated !== parsed.narrated) {
        report.errors.push(`${fileName}: ${markers.narrated} narrator blocks in the page, `
            + `${parsed.narrated} parsed`);
    }
    if (markers.grades !== parsed.grades) {
        report.errors.push(`${fileName}: ${markers.grades} grade blocks in the page, `
            + `${parsed.grades} parsed`);
    }
    if (markers.comment !== null && markers.comment !== markers.containers) {
        report.warnings.push(`${fileName}: the page says ${markers.comment} hadith, `
            + `found ${markers.containers} containers`);
    }
    if (markers.collection && markers.collection !== collection) {
        report.errors.push(`${fileName}: page says collection "${markers.collection}"`);
    }
    if (markers.bookID && markers.bookID !== bookNumber) {
        report.errors.push(`${fileName}: page says book ${markers.bookID}`);
    }

    const book = parseBookInfo(content);
    return {
        collection,
        book: { number: bookNumber, english: book.english, arabic: book.arabic },
        chapters: chapters.map(({ n, nAr, en, ar, intro }) => ({ n, nAr, en, ar, intro })),
        hadiths
    };
}

/* --------------------------------------------------------------- main ---- */

async function buildCollection(collection, report) {
    const directory = path.join(SOURCE, collection);
    const files = (await readdir(directory)).filter(name => name.endsWith('.txt'));
    files.sort((a, b) => bookNumberOf(a) - bookNumberOf(b));
    await mkdir(path.join(OUTPUT, collection), { recursive: true });

    const books = [];
    let hadiths = 0;
    let chapters = 0;
    for (const fileName of files) {
        const bookNumber = bookNumberOf(fileName);
        const raw = await readFile(path.join(directory, fileName), 'utf8');
        const content = raw.replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
        const page = parsePage(content, { collection, bookNumber, fileName, report });
        await writeFile(path.join(OUTPUT, collection, `${bookNumber}.json`),
            JSON.stringify(page));
        books.push({
            number: bookNumber,
            english: page.book.english,
            arabic: page.book.arabic,
            hadiths: page.hadiths.length,
            chapters: page.chapters.length,
            file: `${collection}/${bookNumber}.json`
        });
        hadiths += page.hadiths.length;
        chapters += page.chapters.length;
    }
    report.collections.push({ id: collection, books: books.length, hadiths, chapters });
    return books;
}

async function main() {
    const clean = process.argv.includes('--clean');
    const started = Date.now();
    const report = { collections: [], warnings: [], gaps: [], errors: [] };

    const entries = await readdir(SOURCE, { withFileTypes: true });
    const collections = entries
        .filter(entry => entry.isDirectory())
        .map(entry => entry.name)
        .sort();

    const catalog = { collections: [] };
    for (const collection of collections) {
        const books = await buildCollection(collection, report);
        const names = COLLECTIONS[collection] || { english: collection, arabic: '' };
        catalog.collections.push({
            id: collection,
            english: names.english,
            arabic: names.arabic,
            hadiths: books.reduce((total, book) => total + book.hadiths, 0),
            chapters: books.reduce((total, book) => total + book.chapters, 0),
            books
        });
    }
    await writeFile(path.join(OUTPUT, 'catalog.json'), JSON.stringify(catalog));

    for (const summary of report.collections) {
        console.log(`${summary.id.padEnd(9)} ${String(summary.books).padStart(3)} books  `
            + `${String(summary.hadiths).padStart(5)} hadiths  `
            + `${String(summary.chapters).padStart(4)} chapters`);
    }
    const totals = report.collections.reduce((sum, item) => ({
        books: sum.books + item.books, hadiths: sum.hadiths + item.hadiths
    }), { books: 0, hadiths: 0 });
    console.log(`${'total'.padEnd(9)} ${String(totals.books).padStart(3)} books  `
        + `${String(totals.hadiths).padStart(5)} hadiths`);

    for (const warning of report.warnings) console.warn(`warning: ${warning}`);
    for (const gap of report.gaps) console.warn(`gap: ${gap}`);
    for (const error of report.errors) console.error(`error: ${error}`);

    if (report.errors.length) {
        console.error(`\n${report.errors.length} problem(s); data/ was kept.`);
        process.exit(1);
    }
    console.log(`\nWrote HadithData/ in ${((Date.now() - started) / 1000).toFixed(1)}s.`);

    if (clean) {
        await rm(SOURCE, { recursive: true, force: true });
        console.log('Removed data/ — HadithData/ is the source of truth now.');
    }
}

main().catch(error => {
    console.error(error.stack || error.message);
    process.exit(1);
});
